// Cards de ajuda do Painel de Implantação. Chaves: fase:<id>, rotina:<k>, tabela:<k>, tarefa:<título exato>, bloco:<nome>
(function(){
const E=(titulo,oque,fazer,porque,como,ajuda,falta)=>({tipo:'Etapa',titulo,oque,fazer,porque,como,ajuda,falta});
const R=(titulo,oque,fazer,porque,como,ajuda,falta)=>({tipo:'Rotina',titulo,oque,fazer,porque,como,ajuda,falta});
const A=(titulo,oque,fazer,porque,como,ajuda,falta)=>({tipo:'Área',titulo,oque,fazer,porque,como,ajuda,falta});
const T=(oque,fazer,porque,como,ajuda,falta)=>({tipo:'Tarefa',oque,fazer,porque,como,ajuda,falta});
const NAO_SABE='Se você não encontrar a informação, não chute e não escolha qualquer opção. Deixe o campo em branco (ele aparece como A DEFINIR) ou marque “Precisa investigar”, e escreva nas observações o que falta descobrir.';
const PERGUNTE='Isso depende de uma decisão da empresa. Não decida sozinha: mude o status da tarefa para “Aguardando decisão” e escreva nas observações qual é a pergunta para o responsável.';

window.PAINEL_AJUDA = {
'__padrao_falta': NAO_SABE,

// ——— BLOCOS GERAIS ———
'bloco:progresso': A('Progresso geral da organização','É o número que mostra quanto da organização já foi feita, de 0% a 100%.',['Acompanhar esse número no dia a dia.','Entender que ele só sobe quando as tarefas avançam de verdade.'],'Sem um número, é difícil saber se a organização está andando ou parada.',['Cada tarefa vale pontos conforme o status: “Em levantamento” vale pouco, “Em execução” vale metade, “Concluído” vale quase tudo e “Validado” vale tudo.','Os itens da checklist final também contam.','Para o número subir, atualize o status das tarefas sempre que avançar.'],'Mostra para você e para o responsável, sem conversa, quanto falta para a operação estar organizada e o painel poder ser encerrado.','Se o número parecer errado, confira se os status das tarefas estão atualizados.'),
'bloco:prioridades': A('Próximas prioridades','É a lista do que você deve fazer agora. O painel escolhe as tarefas mais importantes que ainda não foram concluídas.',['Começar o dia por esta lista.','Abrir a primeira tarefa e trabalhar nela.'],'Com muita coisa para fazer, é comum começar pelo que é mais fácil e deixar o importante para depois.',['Clique na tarefa para ver todos os detalhes.','Comece pelas de prioridade Alta das primeiras fases.','Quando começar a trabalhar, mude o status para “Em levantamento” ou “Em execução”.','Ao terminar, mude para “Concluído”.'],'Garante que o esforço vai primeiro para o que mais afeta a operação.','Se não souber como começar uma tarefa, clique no “?” ao lado do nome dela.'),
'bloco:travado': A('O que está travado','São as tarefas que não conseguem andar: estão bloqueadas ou esperando uma decisão do responsável.',['Sempre que uma tarefa parar por falta de informação, acesso ou decisão, marque o status correto.','Escrever nas observações o motivo exato do travamento.'],'Uma tarefa parada sem ninguém saber vira um atraso invisível.',['Use “Bloqueado” quando falta algo para continuar (um acesso, um arquivo, uma resposta).','Use “Aguardando decisão” quando o responsável precisa escolher algo.','Nas observações, escreva de forma clara o que é preciso para destravar.','Revise esta lista com o responsável com frequência.'],'O responsável vê de uma vez tudo o que depende dele, sem precisar perguntar.','Se não souber se é bloqueio ou decisão, use “Aguardando decisão” e explique nas observações.'),
'bloco:mapa': A('Mapa de implantação','É a lista das 13 fases da organização, com a situação e o percentual de cada uma.',['Ver quais fases já andaram e quais ainda nem começaram.','Clicar em uma fase para abrir.'],'A organização tem muitas partes. O mapa mostra o todo de uma vez.',['Uma fase fica “Em andamento” assim que qualquer tarefa dela começa.','Ela só fica “Concluída” quando todas as tarefas estão concluídas e validadas.','Clique na linha para ir até a fase.'],'Ajuda a perceber se alguma área está esquecida enquanto outras avançam.'),
'bloco:tarefas': A('Todas as tarefas','É a lista completa de tarefas do painel, de todas as fases.',['Usar os filtros para encontrar o que procura.','Clicar em uma tarefa para abrir e editar.'],'Às vezes você precisa ver, por exemplo, tudo que está bloqueado ou tudo de uma área.',['Escolha uma fase, área, prioridade ou status nos filtros.','A lista mostra só o que combina com os filtros.','Clique em “Limpar filtros” para ver tudo de novo.'],'Permite achar qualquer tarefa em segundos, sem depender da memória.'),
'bloco:tarefas-fase': A('Tarefas desta fase','São as tarefas que precisam ser feitas para esta fase ficar pronta.',['Abrir cada tarefa clicando nela.','Ler o que fazer, como fazer e por que fazer.','Marcar os itens da checklist conforme avança.','Atualizar o status.'],'Cada fase só termina quando todas as tarefas dela estão concluídas.',['Clique no nome da tarefa para abrir os detalhes.','Clique no “?” para uma explicação passo a passo.','Marque os itens da checklist à medida que forem feitos.','Mude o status conforme avança. Use “+ Nova tarefa” se descobrir algo que precisa ser feito e não está na lista.','Use “Editar todos os campos” para escrever observações e pendências.'],'Transforma cada fase em uma sequência clara de ações, com fim definido.','Se descobrir algo novo que precisa ser feito, crie uma nova tarefa em vez de guardar na cabeça.'),
'bloco:status': A('Status das tarefas','O status diz em que ponto a tarefa está.',['Escolher o status que descreve a situação real da tarefa agora.'],'É pelo status que o painel calcula o progresso e mostra o que está travado.',['Não iniciado: ninguém começou.','Em levantamento: você está descobrindo informações.','Em execução: você já sabe o que fazer e está fazendo.','Aguardando decisão: o responsável precisa decidir algo.','Bloqueado: falta algo para continuar (acesso, arquivo, resposta).','Concluído: você terminou e o critério de conclusão foi atendido.','Validado: o responsável conferiu e confirmou que está certo.'],'Deixa claro para todos o que está andando, o que está parado e o que está pronto.','Na dúvida entre Concluído e Validado: só marque Validado depois que o responsável conferir.'),
'bloco:regras': A('Regras da empresa','São as regras de cobrança e de cancelamento que só a empresa pode definir.',['Pedir ao responsável que preencha estes campos.','Ler as regras antes de agir em assinaturas ou cancelamentos.'],'Regras de cobrança e cancelamento envolvem dinheiro e direitos do cliente. Não podem ser inventadas.',['Mostre estes campos ao responsável.','Peça que escreva as regras com as palavras dele.','Quando surgir um caso que as regras não cobrem, anote a dúvida e leve ao responsável.'],'Todos passam a seguir a mesma regra, e o cliente recebe a mesma resposta, não importa quem atenda.',PERGUNTE),
'bloco:checklist-final': A('Checklist de encerramento','É a lista final que confirma se a operação está realmente organizada.',['Marcar cada item só quando ele for verdade.','Revisar a lista junto com o responsável.'],'O painel é temporário. Antes de deixar de usá-lo, é preciso ter certeza de que nada importante ficou para trás.',['Leia cada item com calma.','Pergunte: “Isso já está pronto e fora da cabeça das pessoas?”.','Se a resposta for sim, marque. Se for “quase”, não marque.','Quando todos estiverem marcados e as tarefas validadas, o painel mostra “100% organizado”.'],'Evita encerrar a implantação com dependências escondidas que trariam a bagunça de volta.','Se um item não se aplica à empresa, combine com o responsável e anote isso nas observações da tarefa de revisão da checklist antes de marcar.'),

// ——— ETAPAS ———
'fase:overview': E('Visão geral','É a tela inicial do painel. Mostra onde a organização está, o que fazer agora e o que está travado.',['Abrir esta tela no começo do dia.','Começar pelas próximas prioridades.','Conferir se algo está travado.'],'Com muitas coisas acontecendo ao mesmo tempo, é fácil perder o fio. Esta tela mostra tudo sem depender da memória.',['Veja o percentual geral.','Leia as “Próximas prioridades” e abra a primeira.','Confira “O que está travado” e leve ao responsável o que depender dele.','Use o menu para ir até cada fase.'],'Responsável e contratada olham para a mesma informação e sabem exatamente quanto falta para encerrar a implantação.'),
'fase:f1': E('Operação diária','É a rotina que precisa ser cumprida todos os dias, sem exceção: responder os clientes, recuperar vendas e fazer as entregas.',['Responder todos os canais de comunicação com o cliente.','Recuperar vendas: PIX pendente, cartão recusado e abandono de carrinho.','Fazer a entrega: boas-vindas, grupo e o que o aluno adquiriu.','Acompanhar o aluno do front no upsell.'],'Cliente sem resposta, venda sem recuperação ou aluno sem entrega são os problemas que mais custam para a operação.',['Comece o dia passando por todos os canais de atendimento.','Depois, faça a recuperação de vendas pendentes.','Em seguida, garanta boas-vindas, grupo e entrega de cada aluno novo.','Se o aluno do front tiver cartão recusado ou PIX pendente no upsell, faça a recuperação imediatamente, junto com a entrega do front.'],'Mantém a operação funcionando todos os dias. Quando o CRM for estruturado, cada item desta rotina vira uma etapa a configurar.'),
'fase:f2': E('Infraestrutura e acessos','É a lista de tudo o que você precisa acessar para trabalhar: e-mail, WhatsApp, plataformas, arquivos e locais de materiais.',['Descobrir quais acessos são necessários.','Registrar cada um na tabela.','Conseguir e testar cada acesso.'],'Sem acesso, você não consegue atender, recuperar pagamentos nem entregar produtos.',['Comece pelo e-mail e pelo WhatsApp de trabalho.','Pergunte ao responsável quais plataformas a empresa usa.','Registre cada uma e anote para que ela serve.','Teste o login.'],'No final, todos os acessos estão listados em um lugar e ninguém precisa ficar perguntando senha ou endereço.','Não invente e-mails, números ou nomes de plataformas. Se ainda não sabe, deixe em branco.'),
'fase:f3': E('Produtos','É a página de cada produto da empresa, com tudo o que você precisa saber para atender, vender e entregar.',['Abrir o produto antes de atender um aluno dele.','Conferir se o produto está ativo, rodando e se pode ser vendido.'],'Com as informações de cada produto em um só lugar, você responde o aluno sem precisar perguntar.',['Clique em “Ver produto” para abrir.','Leia o briefing para entender o produto.','Confira o que é entregue, entregáveis, grupo e como o aluno recebe acesso.','Antes de vender, confira “Posso vender?”.'],'Garante que todos falem a mesma coisa sobre cada produto.'),
'fase:f4': E('Mapa de grupos','É a lista de todos os grupos de WhatsApp que existem ou já foram usados pela empresa.',['Encontrar os grupos.','Registrar cada um.','Relacionar ao produto e classificar.'],'Existem grupos de vários produtos e lançamentos. Sem organização, não se sabe onde colocar um cliente novo nem quais grupos precisam de atenção.',['Verifique os números de WhatsApp da operação.','Registre cada grupo encontrado.','Indique o produto, a finalidade e a situação.'],'Fica claro quais grupos ainda são usados, a que produto pertencem e quais são apenas antigos.'),
'fase:f5': E('Funis','É o cadastro de todos os funis da empresa: os que estão rodando, os que estão parados e os que já rodaram, com tudo o que compõe cada um.',['Cadastrar cada funil.','Adicionar todas as etapas (front, upsells, downsells, order bumps).','Preencher links, entregáveis, recuperação, grupo e números.'],'Suporte, entrega e recuperação dependem de saber exatamente o que o aluno comprou e o que vem depois.',['Clique em “+ Novo funil”.','Preencha o nome e a situação.','No bloco Sobre esse funil fica o contexto geral, escrito pelo responsável.','Adicione cada etapa e preencha os campos.','Volte à lista para ver todos os funis.'],'Qualquer pessoa consegue entender um funil inteiro sem perguntar: o que é vendido, por quanto, o que é entregue e como recuperar.'),
'fase:f6': E('Assinaturas','É organizar as assinaturas (produtos com cobrança recorrente): descobrir quais existem, em que situação estão e como serão acompanhadas.',['Descobrir quais produtos têm assinatura.','Descobrir onde as assinaturas são controladas.','Classificar cada assinatura.','Definir a rotina de acompanhamento.'],'Assinatura sem acompanhamento gera cobrança com problema, cliente insatisfeito e receita perdida.',['Consulte o Mapa de produtos para ver quais têm assinatura.','Registre as assinaturas na tabela com a situação.','Peça ao responsável as regras de cobrança.'],'A empresa passa a saber quantas assinaturas estão ativas, vencendo, vencidas ou com problema, e o que fazer com cada uma.',PERGUNTE),
'fase:f7': E('Cancelamentos','É organizar os pedidos de cancelamento para que nenhum se perca em mensagens.',['Descobrir por onde os pedidos chegam.','Registrar os pedidos pendentes.','Criar um fluxo único.','Definir quando um pedido está encerrado.'],'Pedido esquecido vira cobrança indevida, reclamação e às vezes disputa de pagamento.',['Registre todo pedido na tabela, mesmo os antigos.','Siga o fluxo de etapas de cada pedido.','Peça ao responsável as regras de cancelamento.'],'Todos os pedidos ficam visíveis e têm um fim claro.',PERGUNTE),
'fase:f8': E('Materiais, entregas e acessos','É deixar claro o que cada cliente recebe ao comprar, onde esse material está e como ele é entregue.',['Para cada produto, registrar o que é entregue, onde está e como enviar.','Identificar entregas que dependem de alguém lembrar.'],'Se só uma pessoa sabe onde está o material, a entrega falha quando ela não está.',['Use a tabela “Entregas por produto”. Ela mostra os dados do Mapa de produtos.','Clique em um produto para completar os campos.','Anote como pendência tudo o que estiver espalhado ou indefinido.'],'Qualquer pessoa consegue entregar qualquer produto sem perguntar a ninguém.'),
'fase:f9': E('Procedimentos a criar','É escrever o passo a passo oficial de cada situação da operação (novo comprador, PIX pendente, cancelamento…).',['Preencher a estrutura de cada procedimento conforme a operação for descoberta.','Revisar com o responsável.','Testar na prática.'],'Procedimento escrito permite que qualquer pessoa faça o trabalho do mesmo jeito, sem depender de memória.',['Só escreva depois de entender como a situação funciona de verdade.','Use o que foi anotado em “Como fazer” e “Onde fazer” da Operação diária.','Responda os cinco campos: quando usar, o que fazer, como fazer, onde fazer e quando está concluído.'],'Os procedimentos viram o manual oficial da operação quando o painel for encerrado.','Não escreva um procedimento “imaginando” como deveria ser. Se não sabe, deixe em “A estruturar”.'),
'fase:f10': E('Ferramentas / necessidades','É registrar problemas da operação que talvez precisem de uma ferramenta para serem resolvidos.',['Identificar o problema primeiro.','Registrar como é feito hoje.','Só depois pensar se precisa de ferramenta.','Levar para a decisão do responsável.'],'Não queremos contratar ferramentas sem necessidade. Primeiro é preciso entender onde existe um problema real.',['Comece sempre pelo problema. Exemplo: “Estamos perdendo pedidos de suporte porque as mensagens estão espalhadas.”','Registre na tabela de necessidades.','Não escreva nomes de ferramentas ou marcas; a decisão é da empresa.'],'A empresa contrata ferramentas somente quando elas resolvem problemas reais.',PERGUNTE),
'fase:f11': E('Oportunidades de automação','É anotar tarefas repetitivas feitas à mão que talvez possam acontecer sozinhas no futuro.',['Perceber o que você repete muitas vezes.','Registrar com frequência e problema.','Levar para decisão.'],'Automatizar um processo bagunçado só faz a bagunça acontecer mais rápido. Por isso primeiro se organiza, depois se automatiza.',['Durante a Operação diária, anote o que se repete.','Registre na tabela: qual é a tarefa, quantas vezes acontece e qual o problema.','Descreva o que deveria acontecer sozinho, sem citar ferramenta.'],'Reduz trabalho manual no futuro, nos pontos certos.'),
'fase:f12': E('Migração para a operação definitiva','É levar cada coisa organizada aqui para o seu lugar definitivo, fora do painel.',['Definir o destino de cada item.','Levar a informação para lá.','Confirmar que nada ficou só no painel.'],'O painel é temporário. Se a informação ficar só aqui, ele vira mais uma fonte paralela e a bagunça continua.',['Para cada linha da tabela, preencha o local definitivo (decidido com o responsável).','Leve a informação e marque “Migrado”.','Peça ao responsável para conferir e marque “Validado”.'],'Quando tudo estiver migrado, a operação funciona sem este painel.',PERGUNTE),
'fase:f13': E('Validação final','É a conferência final antes de encerrar o painel.',['Revisar a checklist de encerramento com o responsável.','Operar uma semana sem usar o painel.'],'Só dá para encerrar quando a operação não depende mais de informação desorganizada nem da memória de alguém.',['Percorra a checklist item por item.','Marque só o que for verdade.','Faça o teste da semana sem o painel e anote se precisou dele.'],'É o que garante que a organização é real e vai se manter.'),

// ——— ROTINAS ———
'rotina:suporte': R('Suporte','É atender os clientes que entram em contato com dúvidas, problemas ou pedidos.',['Verificar os atendimentos novos.','Responder.','Resolver o que conseguir.','Registrar o que ficou pendente e acompanhar até resolver.'],'Cliente sem resposta fica insatisfeito, reclama e pode pedir reembolso ou cancelamento.',['Veja todos os canais onde chegam mensagens de clientes.','Responda cada um.','Se não conseguir resolver na hora, registre em “Pendências de suporte” com a próxima ação.','Marque a “Rotina de hoje” conforme avança.','Antes de encerrar o dia, revise as pendências abertas.'],'Nenhum cliente fica esquecido e o responsável vê o que está pendente sem precisar perguntar.','Se não souber responder algo, não invente. Registre como pendência e leve a dúvida ao responsável.'),
'rotina:pix': R('Recuperação de PIX','É entrar em contato com uma pessoa que iniciou uma compra por PIX mas ainda não pagou.',['Identificar os PIX gerados e ainda pendentes.','Identificar o comprador.','Fazer o contato de recuperação.','Acompanhar até saber se pagou ou não.'],'Essa pessoa teve interesse suficiente para iniciar a compra. Se ninguém falar com ela, a venda pode simplesmente se perder.',['Consulte o local onde aparecem os PIX pendentes.','Registre o comprador na tabela.','Faça o contato usando a mensagem e o processo definidos pela empresa.','Atualize a situação e o resultado na tabela.'],'Recupera vendas que seriam perdidas e evita que compradores interessados fiquem esquecidos.','Se ainda não há mensagem ou prazo definidos pela empresa, pergunte ao responsável antes de começar os contatos.'),
'rotina:cartao': R('Recuperação de cartão recusado','É falar com quem tentou pagar com cartão e teve o pagamento recusado.',['Identificar as tentativas recusadas.','Entrar em contato com o comprador.','Orientar sobre como tentar de novo.','Confirmar se conseguiu pagar.'],'Muitas recusas acontecem por motivos simples (limite, dados errados, bloqueio do banco). A pessoa quer comprar, só precisa de ajuda.',['Consulte o local onde aparecem as tentativas recusadas.','Registre na tabela.','Entre em contato e oriente de acordo com a orientação definida pela empresa.','Acompanhe a nova tentativa e registre o resultado.'],'Recupera vendas e melhora a experiência de quem teve problema para pagar.','Nunca peça dados do cartão ao cliente por mensagem.'),
'rotina:compradores': R('Novos compradores','É uma pessoa que acabou de comprar. A compra não termina quando o pagamento é aprovado: ela precisa receber o que comprou.',['Identificar o comprador.','Conferir o produto comprado.','Fazer as boas-vindas.','Entregar o produto ou o acesso.','Colocar no grupo correto, se existir.','Confirmar que recebeu.'],'Se a pessoa compra e não recebe direito, começa a experiência como cliente com um problema.',['Registre cada novo comprador na tabela.','Consulte o Mapa de produtos para saber o material, o acesso e o grupo.','Abra o registro e marque cada etapa ao concluir.','Só considere concluído quando todas as etapas aplicáveis estiverem marcadas.'],'Garante que cada cliente novo entre corretamente e diminui chamados de suporte por falha na entrega.','Se o produto não estiver no Mapa de produtos, cadastre-o e marque “Precisa investigar”.'),
'rotina:entrega': R('Entrega','É garantir que o comprador receba exatamente o que comprou: material, arquivo, link ou acesso.',['Ver qual produto foi comprado.','Descobrir o que precisa ser entregue e onde está.','Entregar.','Registrar que foi entregue.'],'Entrega esquecida ou errada é uma das maiores causas de reclamação.',['Consulte o Mapa de produtos para saber o que entregar e como.','Registre a entrega na tabela.','Faça a entrega e marque “Entregue: Sim”.'],'Nenhum comprador fica sem receber, e fica registrado quando cada entrega aconteceu.','Se não souber onde está o material, registre a entrega como pendente e avise o responsável.'),
'rotina:grupos': R('Inclusão em grupos','É colocar o comprador no grupo de WhatsApp correto, quando o produto tem grupo.',['Descobrir qual é o grupo certo.','Adicionar o comprador.','Confirmar que ele entrou.'],'Quem fica fora do grupo perde conteúdo e aviso, e acaba procurando o suporte.',['Consulte o Mapa de produtos e o Mapa de grupos.','Registre a inclusão na tabela.','Adicione o comprador e marque as etapas.'],'Cada cliente fica no grupo certo e os grupos refletem quem realmente comprou.','Se não tiver certeza de qual é o grupo, não adicione em qualquer um. Registre a dúvida.'),
'rotina:cancel': R('Cancelamentos','É tratar cada pedido de cancelamento do início ao fim, sem deixar nada perdido em mensagens.',['Registrar o pedido.','Identificar cliente e produto.','Entender o que foi pedido.','Executar o necessário.','Confirmar para o cliente.'],'Pedido esquecido gera cobrança indevida, reclamação e às vezes disputa de pagamento.',['Registre todo pedido na tabela assim que ele chegar.','Siga as etapas do registro e marque cada uma.','Execute de acordo com as regras de cancelamento da empresa.','Confirme para o cliente e escreva o resultado.'],'Cada pedido tem começo, meio e fim registrados.',PERGUNTE),
'rotina:assin': R('Assinaturas','É acompanhar as assinaturas para agir nas que estão vencendo, vencidas ou com problema de pagamento.',['Registrar as assinaturas conhecidas com a situação.','Olhar os contadores por situação.','Agir conforme as regras da empresa.'],'Assinatura vencida sem acompanhamento é receita perdida e, às vezes, cliente sem acesso.',['Consulte onde as assinaturas são controladas.','Registre ou atualize a situação na tabela.','Siga as regras de cobrança preenchidas pelo responsável.'],'A empresa vê de relance quantas assinaturas precisam de atenção.',PERGUNTE),

// ——— TABELAS ———
'tabela:emails': A('E-mails','É a lista dos e-mails que você usa para trabalhar.',['Para cada e-mail, preencher na sequência: Acesso, Uso, E-mail e Senha.'],'Deixa claro qual e-mail serve para quê e evita perguntar a senha toda vez.',['Em Acesso, escreva um nome que ajude a identificar (você escolhe).','Em Uso, escreva para que esse e-mail serve.','Preencha o e-mail e a senha confirmados pelo responsável.','Use “+ Adicionar” para cada e-mail novo.'],'Todos os e-mails de trabalho ficam em um só lugar.','Não invente e-mails. Deixe em branco até confirmar. A senha fica salva só neste navegador; não compartilhe o arquivo exportado com quem não deve ter acesso.'),
'tabela:whatsapps': A('WhatsApp','É a lista dos números de WhatsApp usados na operação.',['Para cada número, preencher na sequência: Acesso, Uso, Número e Nome.'],'O cliente precisa falar com o número certo, e você precisa saber para que cada um serve.',['Em Acesso, escreva um nome que ajude a identificar (você escolhe).','Em Uso, escreva para que o número serve (suporte, recuperação…).','Preencha o número e o nome confirmados pelo responsável.'],'Evita conversas espalhadas em números diferentes.','Não invente números. Deixe em branco até confirmar.'),
'tabela:acessos': A('Outros sistemas','São as plataformas e locais que você precisa acessar além de e-mail e WhatsApp.',['Preencher Acesso, Uso, Login e Senha de cada um.','Adicionar novas linhas quando descobrir outro sistema.'],'Deixa todos os acessos em um só lugar.',['Clique em uma linha para editar.','Preencha só o que foi confirmado.','Use “+ Adicionar” para um sistema novo.'],'Ninguém mais precisa perguntar onde entrar.','Não invente nomes de plataformas. A senha fica salva só neste navegador; cuidado ao compartilhar o arquivo exportado.'),
'tabela:produtos': A('Mapa de produtos','É o cadastro de cada produto com tudo o que é preciso para atender e entregar.',['Cadastrar cada produto encontrado.','Preencher os campos operacionais.','Classificar a situação.'],'É a base para entrega, grupos, assinaturas e suporte.',['Clique em “+ Adicionar” para cadastrar.','Clique em uma linha para editar todos os campos.','Situação: Atual (vendendo agora), Antigo (não vende mais), Ainda possui clientes, Descontinuado (encerrado) ou Precisa investigar.'],'Qualquer dúvida sobre um produto passa a ser respondida olhando aqui.',NAO_SABE),
'tabela:grupos': A('Mapa de grupos','É o cadastro de cada grupo de WhatsApp.',['Cadastrar cada grupo.','Indicar produto, finalidade e situação.'],'Mostra onde colocar clientes e quais grupos ainda precisam de atenção.',['Clique em “+ Adicionar”.','Situação: Ativo (em uso), Legado (antigo, ainda com pessoas), Encerrado ou Precisa investigar.','Anote pendências, como “não sei a que produto pertence”.'],'Fica claro quais grupos existem e para que serve cada um.',NAO_SABE),
'tabela:clientes': A('Clientes em organização','É uma tabela temporária para organizar clientes que precisam de alguma correção ou migração.',['Registrar clientes que têm pendência ou que precisam ser levados para o local definitivo.'],'Ajuda a organizar sem criar um novo cadastro paralelo.',['Registre cliente, contato, produto e situação.','Escreva a pendência de forma clara.','Quando a pendência for resolvida e o cliente estiver no local definitivo, ele pode sair daqui.'],'Deixa visível o que falta resolver sobre clientes.','Não copie a base inteira para cá. Esta tabela serve para organizar e migrar.'),
'tabela:suporte': A('Pendências de suporte','São os atendimentos que não foram resolvidos no primeiro contato.',['Registrar cada pendência.','Escrever a próxima ação.','Acompanhar até resolver.'],'Pendência que não é anotada é esquecida.',['Registre cliente e assunto.','Na “Próxima ação”, escreva o que precisa acontecer (ex.: “aguardar resposta do cliente”).','Mude a situação para “Resolvida” quando terminar.'],'Nenhum cliente fica sem retorno.'),
'tabela:pix': A('Recuperação de PIX','É o controle de cada PIX pendente e do contato feito.',['Registrar cada PIX pendente.','Atualizar a situação e o resultado.'],'Sem registro, não se sabe com quem já foi falado.',['Registre comprador e produto.','Situação: acompanhe da geração até Pago ou Não pago.','Resultado: Em andamento, Recuperado ou Não recuperado.'],'Mostra quantas vendas foram recuperadas.'),
'tabela:cartao': A('Recuperação de cartão recusado','É o controle de cada tentativa recusada e do contato feito.',['Registrar cada recusa.','Atualizar situação e resultado.'],'Sem registro, alguns compradores recebem vários contatos e outros nenhum.',['Registre comprador e produto.','Atualize a situação a cada passo.','Feche com Recuperado ou Não recuperado.'],'Mostra quantas vendas foram recuperadas.'),
'tabela:compradores': A('Novos compradores','É o controle de cada comprador novo, etapa por etapa.',['Registrar o comprador.','Marcar cada etapa ao concluir.'],'A barra de etapas mostra rápido quem ainda não recebeu tudo.',['Clique em “+ Adicionar” e preencha comprador e produto.','Marque as etapas conforme forem feitas.','Se uma etapa não se aplica (ex.: produto sem grupo), escreva isso nas observações.'],'Nenhum comprador fica no meio do caminho.'),
'tabela:entregas': A('Entregas','É o controle do que precisa ser entregue a cada comprador.',['Registrar cada entrega.','Marcar quando foi entregue.'],'Garante que nenhuma entrega fique esquecida.',['Registre cliente e produto.','Consulte o Mapa de produtos para preencher o que entregar e onde está.','Marque “Entregue: Sim” ao concluir.'],'Mostra de relance o que falta entregar.'),
'tabela:inclusoes': A('Inclusão em grupos','É o controle de quem precisa entrar em algum grupo.',['Registrar o comprador e o grupo correto.','Marcar quando foi adicionado e quando a entrada foi confirmada.'],'Evita cliente esquecido fora do grupo.',['Consulte o Mapa de grupos para achar o grupo certo.','Marque as duas etapas.'],'Todo comprador que tem direito a grupo está nele.'),
'tabela:cancel': A('Pedidos de cancelamento','É o controle de cada pedido de cancelamento, do recebimento até a confirmação para o cliente.',['Registrar todo pedido.','Marcar as etapas.','Escrever o resultado.'],'Tira os pedidos das mensagens soltas.',['Registre cliente, produto e por onde chegou.','Descreva o que foi solicitado.','Marque cada etapa ao concluir.','No resultado, escreva o que foi feito.'],'Todo pedido tem um fim registrado.',PERGUNTE),
'tabela:assinaturas': A('Assinaturas','É o controle da situação de cada assinatura conhecida.',['Registrar cada assinatura com situação e vencimento.','Atualizar quando mudar.'],'Os contadores acima da tabela mostram onde agir primeiro.',['Registre cliente, produto e situação.','Anote o vencimento, se souber.','Atualize a situação quando algo mudar.'],'A empresa vê a saúde das assinaturas sem abrir vários sistemas.',NAO_SABE),
'tabela:materiais': A('Entregas por produto','É uma visão do Mapa de produtos focada em entrega: o que o cliente recebe, onde está, como recebe acesso e o que depende de memória.',['Completar os campos de entrega de cada produto.'],'Aqui fica fácil ver quais produtos ainda têm entrega indefinida.',['Clique em um produto para abrir e editar.','Preencha material, local, acesso, entrega manual e dependência de memória.','Os dados são os mesmos do Mapa de produtos.'],'Qualquer pessoa consegue entregar qualquer produto.',NAO_SABE),
'tabela:procedimentos': A('Procedimentos a criar','É a estrutura dos procedimentos oficiais, para ser preenchida conforme a operação for entendida.',['Preencher os cinco campos de cada procedimento.','Atualizar a situação.'],'Transforma o que está na cabeça das pessoas em um passo a passo.',['Quando usar: em que situação o procedimento vale.','O que fazer: o objetivo.','Como fazer: os passos.','Onde fazer: em qual sistema ou canal.','Quando está concluído: como saber que terminou.','Situação: A estruturar → Em preenchimento → Em revisão → Documentado.'],'Vira o manual da operação.','Não escreva o procedimento sem saber como a situação funciona. Deixe em “A estruturar”.'),
'tabela:ferramentas': A('Necessidades identificadas','É o registro de problemas que talvez precisem de uma ferramenta.',['Descrever o problema.','Descrever como é feito hoje.','Aguardar a decisão do responsável.'],'A empresa decide o que contratar com base em problemas reais.',['Comece pelo problema, não pela ferramenta.','Preencha tarefa afetada, como é feito hoje e o que precisa ser resolvido.','Deixe a decisão para o responsável.'],'Evita contratações desnecessárias.',PERGUNTE),
'tabela:automacoes': A('Oportunidades de automação','É o registro de tarefas manuais repetitivas.',['Registrar a tarefa, a frequência e o problema.','Descrever o que deveria acontecer sozinho.'],'Ajuda a escolher o que vale a pena automatizar.',['Preencha processo e tarefa manual.','Frequência: quantas vezes acontece (por dia, por semana).','Situação: Identificada → Em análise → Aprovada → Implantada, ou Descartada.'],'Reduz trabalho repetitivo depois que a operação estiver organizada.'),
'tabela:migracao': A('Destino definitivo','É a lista do que precisa sair do painel e ir para o seu lugar definitivo.',['Preencher o local definitivo de cada item.','Atualizar a situação da migração.'],'Enquanto a informação estiver só aqui, o painel não pode ser encerrado.',['“Vira” mostra o tipo de destino.','“Local definitivo” é onde vai ficar, decidido pelo responsável.','Situação: Não iniciado → Em migração → Migrado → Validado.'],'Garante que o painel pode ser desligado sem perder nada.',PERGUNTE),

// ——— TAREFAS ———
'tarefa:Definir a rotina diária de suporte': T('É combinar como e quando o suporte vai ser feito todos os dias, para nenhum cliente ficar sem resposta.',['Descobrir por onde os clientes entram em contato.','Definir horários para olhar as mensagens.','Seguir a rotina por 5 dias seguidos.'],'Sem rotina, o suporte acontece “quando dá”, e alguns clientes esperam demais ou são esquecidos.',['Liste todos os canais onde chegam mensagens de clientes (pergunte ao responsável).','Combine com o responsável os horários de verificação.','Use a “Rotina de hoje” em Operação diária › Suporte.','Registre toda pendência na tabela.','Depois de 5 dias, revise as pendências com o responsável.'],'O suporte passa a ter um ritmo previsível, e o responsável consegue ver o que ficou pendente.'),
'tarefa:Iniciar a recuperação de PIX pendente': T('É começar a falar com as pessoas que geraram um PIX e não pagaram.',['Descobrir onde ver os PIX pendentes.','Combinar a mensagem com o responsável.','Fazer os contatos e registrar os resultados.'],'Essa pessoa quase comprou. Um contato no momento certo pode recuperar a venda.',['Pergunte ao responsável onde aparecem os PIX gerados e não pagos.','Combine a mensagem e o prazo de contato.','Registre cada caso na tabela de Recuperação de PIX.','Atualize o resultado de cada contato.'],'Recupera vendas e cria o processo que vai continuar depois da implantação.','Se a mensagem ou o prazo ainda não foram definidos, marque “Aguardando decisão” e não improvise.'),
'tarefa:Iniciar a recuperação de cartão recusado': T('É começar a falar com quem teve o pagamento com cartão recusado.',['Descobrir onde ver as recusas.','Combinar a orientação com o responsável.','Fazer os contatos e registrar.'],'A pessoa queria comprar. Muitas vezes só precisa de ajuda para tentar de novo.',['Pergunte ao responsável onde aparecem as tentativas recusadas.','Combine qual orientação dar ao cliente.','Registre cada caso na tabela.','Acompanhe a nova tentativa e registre o resultado.'],'Recupera vendas perdidas por problemas simples de pagamento.','Nunca peça número de cartão ou senha por mensagem.'),
'tarefa:Garantir a sequência de novos compradores': T('É garantir que todo comprador novo passe por todas as etapas: boas-vindas, entrega, acesso e grupo.',['Descobrir como você fica sabendo de uma compra nova.','Combinar a mensagem de boas-vindas.','Saber o material e o grupo de cada produto.','Registrar e acompanhar cada comprador.'],'Comprador que não recebe acesso ou material procura o suporte ou pede reembolso.',['Pergunte ao responsável como uma venda nova aparece.','Combine a mensagem de boas-vindas.','Use o Mapa de produtos para saber o que entregar.','Registre cada comprador na tabela e marque as etapas.'],'Cada cliente novo começa bem e o suporte recebe menos reclamações.'),
'tarefa:Parar de perder pedidos de cancelamento': T('É garantir que todo pedido de cancelamento seja anotado e tratado até o fim.',['Registrar todos os pedidos a partir de hoje.','Seguir as etapas de cada pedido.','Confirmar para o cliente.'],'Pedido esquecido vira cobrança indevida e reclamação.',['Sempre que chegar um pedido, registre na tabela de Cancelamentos.','Siga as etapas do registro.','Aja conforme as regras da empresa.','Confirme ao cliente e escreva o resultado.'],'Nenhum pedido se perde, e a empresa sabe quantos pedidos recebe.',PERGUNTE),
'tarefa:Acompanhar assinaturas vencendo e vencidas': T('É começar a olhar para as assinaturas que estão para vencer, já venceram ou têm problema de pagamento.',['Descobrir onde ver os vencimentos.','Pedir as regras de cobrança.','Registrar as assinaturas com problema.'],'Assinatura vencida sem acompanhamento é receita perdida.',['Pergunte ao responsável onde as assinaturas são controladas.','Peça que ele preencha as regras de cobrança no painel.','Registre as assinaturas com problema na tabela.'],'A empresa começa a agir nas assinaturas antes de perder o cliente.',PERGUNTE),
'tarefa:Definir o e-mail de trabalho da contratada': T('É definir qual e-mail você vai usar para entrar nos sistemas da empresa.',['Combinar o e-mail com o responsável.','Registrar na tabela de acessos.','Testar.'],'Todos os acessos vão ser criados para esse e-mail. Sem ele definido, cada acesso vira uma dúvida.',['Pergunte ao responsável qual e-mail deve ser usado.','Registre na linha “E-mail utilizado pela pessoa contratada”.','Envie um teste para confirmar que funciona.'],'Deixa claro para todos por onde você recebe acessos e avisos.','Não crie e não invente um e-mail por conta própria.'),
'tarefa:Definir os números de WhatsApp de trabalho': T('É definir qual número vai ser usado para suporte e se a recuperação de pagamentos usa outro número.',['Combinar os números com o responsável.','Registrar na tabela de acessos.'],'O cliente precisa de um canal certo para falar com a empresa.',['Pergunte ao responsável qual é o número de suporte.','Pergunte se a recuperação usa o mesmo número ou outro.','Registre nas linhas correspondentes da tabela de acessos.'],'Evita que clientes falem com números diferentes e que conversas se percam.','Não invente números. Deixe em branco até confirmar.'),
'tarefa:Levantar plataformas de pagamento e de produtos': T('É descobrir em quais sistemas a empresa vende, recebe pagamentos e entrega os produtos.',['Listar as plataformas.','Pedir acesso.','Testar o login.'],'Sem acesso a esses sistemas não dá para recuperar pagamentos nem entregar produtos.',['Pergunte ao responsável quais plataformas a empresa usa.','Registre cada uma na tabela de acessos com a finalidade.','Peça o acesso para o seu e-mail de trabalho.','Entre e confirme que funciona.'],'Todas as plataformas ficam listadas e acessíveis.','Registre só as plataformas que o responsável confirmar.'),
'tarefa:Localizar arquivos, documentos e materiais': T('É descobrir onde estão guardados os arquivos e materiais que são entregues aos clientes.',['Perguntar e procurar onde os materiais estão.','Registrar cada local na tabela de acessos.'],'Material que só uma pessoa sabe onde está trava a entrega.',['Pergunte ao responsável onde os materiais ficam.','Registre cada local encontrado.','Anote nas observações quais materiais estão em cada local.'],'Qualquer pessoa consegue achar um material sem perguntar.'),
'tarefa:Registrar sistemas encontrados no levantamento': T('É anotar qualquer sistema novo que você descobrir durante o trabalho.',['Sempre que aparecer um sistema que não está na tabela, adicioná-lo.'],'É comum descobrir sistemas esquecidos no meio do caminho.',['Vá em Acessos.','Clique em “+ Adicionar”.','Escreva o nome e para que serve.'],'A tabela de acessos fica completa e confiável.'),
'tarefa:Levantar todos os produtos já vendidos': T('É fazer uma lista de todos os produtos que a empresa já vendeu, inclusive os antigos.',['Procurar em todos os lugares onde existem registros de vendas.','Cadastrar cada produto no Mapa de produtos.'],'Hoje há vários produtos e as informações não estão em um único lugar. Antes de organizar clientes, entregas, grupos ou assinaturas, é preciso saber quais produtos existem.',['Procure nos locais onde a empresa já vendeu.','Procure nas áreas de membros, se existirem.','Pergunte ao responsável sobre produtos antigos.','Cadastre cada produto encontrado no Mapa de produtos.'],'A empresa passa a ter uma visão clara de todos os produtos e de quais ainda têm clientes, grupos, materiais, assinaturas ou pendências.','Se encontrar um produto e não souber nada sobre ele, cadastre mesmo assim e marque “Precisa investigar”.'),
'tarefa:Classificar a situação de cada produto': T('É dizer, para cada produto, se ele está sendo vendido agora, se é antigo, se ainda tem clientes ou se foi encerrado.',['Abrir cada produto e escolher a situação.'],'A situação mostra onde concentrar o suporte e a organização.',['Atual: está sendo vendido agora.','Antigo: não é mais vendido.','Ainda possui clientes: tem pessoas usando ou precisando de suporte.','Descontinuado: foi encerrado.','Precisa investigar: você ainda não sabe.'],'Separa o que precisa de atenção do que já pode ser esquecido.',NAO_SABE),
'tarefa:Registrar entrega, acesso e grupo de cada produto': T('É anotar, para cada produto, como ele é entregue, como o cliente recebe acesso, se tem grupo e se tem assinatura.',['Abrir cada produto no mapa.','Preencher os campos de operação.'],'Sem isso, a entrega depende da memória de alguém.',['Abra o produto no Mapa de produtos.','Preencha como é feita a entrega, material, onde está, como recebe acesso, grupo e assinatura.','O que não souber, deixe em branco e escreva em Pendências.'],'Qualquer pessoa sabe o que fazer quando alguém compra aquele produto.',NAO_SABE),
'tarefa:Identificar produtos antigos que ainda exigem suporte': T('É descobrir quais produtos antigos ainda têm clientes que podem precisar de ajuda.',['Para cada produto antigo, verificar se ainda há clientes.','Preencher o campo de suporte.'],'Clientes de produtos esquecidos também têm direito a atendimento.',['Pergunte ao responsável quais produtos antigos ainda têm clientes.','Verifique se chegam mensagens sobre eles no suporte.','Marque “Clientes que ainda precisam de suporte” no produto.'],'Evita surpresas com clientes de produtos que ninguém lembrava.'),
'tarefa:Listar todos os grupos de WhatsApp existentes': T('É descobrir todos os grupos de WhatsApp que existem ou já foram usados pela empresa.',['Localizar os grupos.','Registrar cada um no Mapa de grupos.'],'Há grupos de vários produtos e lançamentos. Sem lista, não se sabe onde colocar um cliente novo.',['Verifique os números de WhatsApp usados pela operação.','Localize os grupos ligados à empresa.','Pergunte ao responsável sobre grupos antigos.','Registre cada grupo no Mapa de grupos.'],'Fica claro quais grupos existem e quais ainda são usados.','Se não souber a que produto um grupo pertence, registre mesmo assim e marque “Precisa investigar”.'),
'tarefa:Relacionar cada grupo ao produto correto': T('É indicar a qual produto cada grupo pertence.',['Abrir cada grupo e preencher o produto relacionado.'],'Sem isso, não dá para saber em qual grupo colocar cada comprador.',['Veja o nome e as mensagens do grupo para entender do que se trata.','Compare com o Mapa de produtos.','Preencha o produto relacionado. Se o grupo não é de nenhum produto, escreva isso.'],'Liga o Mapa de grupos ao Mapa de produtos e facilita a entrega.',NAO_SABE),
'tarefa:Classificar a situação dos grupos': T('É dizer se cada grupo está em uso, é antigo, foi encerrado ou precisa ser investigado.',['Abrir cada grupo e escolher a situação.'],'Mostra quais grupos exigem acompanhamento.',['Ativo: em uso.','Legado: antigo, mas ainda com pessoas.','Encerrado: não é mais usado.','Precisa investigar: você ainda não sabe.'],'Separa os grupos que precisam de cuidado dos que podem ser ignorados.'),
'tarefa:Definir quem deveria estar em cada grupo': T('É anotar quem deveria fazer parte de cada grupo (por exemplo, compradores de um produto).',['Combinar com o responsável.','Preencher o campo no Mapa de grupos.'],'Permite corrigir pessoas que estão no grupo errado ou faltando.',['Pergunte ao responsável qual é o público de cada grupo ativo.','Preencha “Quem deveria estar no grupo”.'],'Os grupos passam a refletir quem realmente tem direito a eles.',PERGUNTE),
'tarefa:Identificar as fontes de clientes': T('É descobrir todos os lugares onde existem dados de clientes: bases, listas, checkouts e planilhas.',['Listar cada fonte.','Anotar o que cada fonte contém.'],'Os dados de clientes estão espalhados. Primeiro é preciso saber onde estão.',['Pergunte ao responsável onde há dados de clientes.','Verifique as plataformas de venda cadastradas em Acessos.','Anote cada fonte nas observações desta tarefa.','Marque os itens da checklist conforme encontrar.'],'É o primeiro passo para centralizar as informações.'),
'tarefa:Identificar os compradores do produto atual': T('É levantar quem comprou o produto que está sendo vendido agora.',['Consultar onde estão os compradores desse produto.','Registrar os que tiverem pendência.'],'É o grupo com mais contato com o suporte hoje.',['Veja no Mapa de produtos qual é o produto atual.','Consulte a fonte de clientes correspondente.','Registre na tabela os compradores com alguma pendência.'],'Garante que os clientes mais recentes estão bem atendidos.'),
'tarefa:Identificar os compradores dos produtos antigos': T('É levantar quem comprou produtos antigos que ainda têm clientes.',['Consultar as fontes.','Registrar os que precisam de algo.'],'Clientes antigos ainda podem precisar de acesso ou suporte.',['Filtre no Mapa de produtos os que “Ainda possuem clientes”.','Consulte as fontes de clientes desses produtos.','Registre na tabela os que tiverem pendência.'],'Evita que clientes antigos fiquem sem atendimento.'),
'tarefa:Identificar os assinantes': T('É levantar quem tem assinatura ativa ou com problema.',['Cruzar com a fase de Assinaturas.'],'Assinantes geram cobrança recorrente e pedidos de cancelamento.',['Consulte onde as assinaturas são controladas.','Registre os assinantes na tabela de Assinaturas.'],'Liga clientes e assinaturas.'),
'tarefa:Decidir onde a informação definitiva de clientes vai ficar': T('É escolher, junto com o responsável, o lugar oficial onde os dados dos clientes vão ficar depois da implantação.',['Mostrar ao responsável as fontes encontradas.','Registrar a decisão.'],'Sem um lugar definitivo, este painel vira mais uma fonte paralela.',['Apresente a lista de fontes encontradas.','Explique os problemas que você viu.','Registre a decisão nas observações e na tabela de Migração.'],'Define para onde as informações de clientes vão.',PERGUNTE),
'tarefa:Centralizar as informações necessárias': T('É levar os dados necessários de clientes para o lugar definitivo escolhido.',['Migrar os dados, produto por produto.','Registrar o avanço.'],'Informação centralizada acaba com a necessidade de procurar em vários lugares.',['Comece pelo produto atual.','Leve os dados para o local definido.','Anote nas observações o que já foi migrado.'],'Qualquer pessoa encontra um cliente sem ajuda.','Só comece depois que o local definitivo tiver sido decidido.'),
'tarefa:Identificar quais produtos têm assinatura': T('É descobrir quais produtos cobram o cliente de forma recorrente (todo mês, por exemplo).',['Ver cada produto e marcar se tem assinatura.'],'Define quais produtos entram na organização de assinaturas.',['Abra cada produto no Mapa de produtos.','Preencha “Possui assinatura / recorrência”.'],'Delimita o trabalho da fase de Assinaturas.',NAO_SABE),
'tarefa:Descobrir onde as assinaturas estão': T('É descobrir em quais sistemas as assinaturas são controladas.',['Perguntar e verificar.','Registrar na tabela de acessos.'],'Sem saber onde estão, não dá para acompanhar vencimentos.',['Pergunte ao responsável.','Registre cada local na tabela de Acessos.','Confirme que você tem acesso.'],'Permite acompanhar as assinaturas de verdade.'),
'tarefa:Classificar as assinaturas por situação': T('É separar as assinaturas conforme a situação: ativas, vencendo, vencidas, com problema, com pedido de cancelamento ou canceladas.',['Registrar cada assinatura com a situação.'],'Mostra onde agir primeiro.',['Consulte o local das assinaturas.','Registre cada uma na tabela desta fase.','Marque os itens da checklist conforme concluir cada grupo.'],'Os contadores passam a mostrar a situação real.',NAO_SABE),
'tarefa:Obter as regras de cobrança com a empresa': T('É pedir para a empresa escrever as regras de cobrança: vencimento, tentativas e o que fazer quando não paga.',['Pedir ao responsável que preencha os campos de regras.'],'Regras de cobrança envolvem dinheiro. Não podem ser decididas por quem executa.',['Mostre ao responsável o bloco “Regras da empresa” nesta fase.','Peça que preencha.','Tire dúvidas e anote nas observações.'],'Todos passam a cobrar do mesmo jeito.',PERGUNTE),
'tarefa:Definir a rotina e o local de acompanhamento': T('É combinar com que frequência e onde as assinaturas serão acompanhadas depois da implantação.',['Propor uma rotina.','Registrar a decisão.'],'Transforma a organização em processo recorrente.',['Proponha ao responsável uma frequência de verificação.','Registre a decisão e o local na tabela de Migração.','Siga a rotina por duas semanas.'],'As assinaturas continuam organizadas depois que o painel acabar.',PERGUNTE),
'tarefa:Descobrir como os pedidos chegam hoje': T('É descobrir por quais canais os clientes pedem cancelamento.',['Listar os canais.'],'Pedidos chegam por lugares diferentes e se perdem.',['Pergunte ao responsável.','Verifique os canais de suporte.','Anote cada canal nas observações.'],'Ninguém mais deixa passar um pedido por não olhar um canal.'),
'tarefa:Identificar e organizar os pedidos pendentes': T('É procurar pedidos de cancelamento antigos que ainda não foram resolvidos.',['Buscar nos canais.','Registrar na tabela.'],'Pedido antigo sem resposta pode virar disputa de pagamento.',['Procure nos canais mapeados.','Registre cada pedido encontrado.','Trate começando pelos mais antigos.'],'Zera o acúmulo de pedidos esquecidos.'),
'tarefa:Definir um fluxo único e o local de registro': T('É combinar um único caminho que todo pedido de cancelamento vai seguir.',['Propor o fluxo.','Registrar a decisão.'],'Um único caminho evita que pedidos se percam.',['Use o fluxo da Operação diária como ponto de partida.','Apresente ao responsável.','Registre onde os pedidos serão registrados após o painel.'],'Qualquer pessoa sabe o que fazer ao receber um pedido.',PERGUNTE),
'tarefa:Documentar como executar um cancelamento': T('É escrever o passo a passo de como um cancelamento é executado.',['Preencher o procedimento “Pedido de cancelamento”.'],'Qualquer pessoa precisa conseguir cancelar sem depender de memória.',['Vá em Procedimentos.','Abra “Pedido de cancelamento”.','Preencha com base no que já foi feito na prática.'],'O cancelamento vira um processo claro e repetível.','Não escreva regras que a empresa ainda não definiu.'),
'tarefa:Definir quando um pedido é considerado encerrado': T('É combinar o que precisa acontecer para um pedido ser dado como terminado.',['Definir o critério com o responsável.','Registrar nas regras.'],'Sem critério, pedidos ficam abertos para sempre.',['Proponha ao responsável (ex.: “ação executada e cliente avisado”).','Peça que registre no campo de regras.'],'Todos sabem quando podem fechar um pedido.',PERGUNTE),
'tarefa:Mapear o que cada produto entrega': T('É anotar o que o cliente recebe quando compra cada produto.',['Preencher “Material a entregar” de cada produto.'],'A entrega não pode depender de memória.',['Abra cada produto.','Escreva o que o cliente recebe (arquivo, acesso, link, grupo…).'],'Todo mundo sabe o que entregar.',NAO_SABE),
'tarefa:Localizar onde cada material está': T('É anotar onde fica guardado o material de cada produto.',['Preencher “Onde está o material”.'],'Material não localizado atrasa a entrega.',['Procure nos locais cadastrados em Acessos.','Registre o local no produto.'],'Qualquer pessoa acha o material.',NAO_SABE),
'tarefa:Identificar entregas manuais e dependências de memória': T('É descobrir o que hoje só acontece porque alguém lembra de fazer.',['Marcar “Entrega manual” e “Depende de memória” em cada produto.'],'São os pontos que mais falham.',['Pergunte: “Se a pessoa que faz isso faltar, alguém consegue fazer?”.','Se a resposta for não, marque “Depende de memória: Sim”.','Anote o que precisa ser registrado.'],'Mostra exatamente o que precisa virar procedimento.'),
'tarefa:Corrigir materiais espalhados ou sem definição': T('É resolver cada problema de material encontrado (material perdido, em vários lugares, sem definição).',['Criar uma subtarefa para cada problema.','Resolver um a um.'],'Deixa a entrega previsível.',['Abra esta tarefa e adicione uma subtarefa por problema.','Resolva com o responsável quando necessário.','Marque cada subtarefa ao concluir.'],'Nenhum produto fica com entrega indefinida.'),
'tarefa:Preencher a estrutura de cada procedimento': T('É preencher, para cada procedimento, os cinco campos: quando usar, o que fazer, como fazer, onde fazer e quando está concluído.',['Preencher com base no que foi aprendido na prática.'],'Procedimento escrito sem conhecer a operação precisa ser refeito.',['Vá em Procedimentos e abra um deles.','Use as anotações de “Como fazer” e “Onde fazer” da Operação diária.','Mude a situação para “Em preenchimento”.'],'Cria o manual da operação.','Se não souber algum campo, deixe em branco e mantenha “A estruturar”.'),
'tarefa:Revisar os procedimentos com o responsável': T('É mostrar cada procedimento ao responsável para ele confirmar que está certo.',['Revisar juntos.','Atualizar a situação.'],'Garante que o procedimento segue as regras da empresa.',['Marque o procedimento como “Em revisão”.','Revise com o responsável.','Ajuste e marque “Documentado”.'],'Os procedimentos ficam oficiais.'),
'tarefa:Testar os procedimentos na operação real': T('É seguir cada procedimento ao pé da letra pelo menos uma vez.',['Executar e anotar ajustes.'],'Procedimento que não funciona na prática não serve.',['Na próxima vez que a situação acontecer, siga o texto.','Anote o que faltou ou confundiu.','Ajuste o procedimento.'],'Os procedimentos ficam confiáveis.'),
'tarefa:Registrar os problemas operacionais encontrados': T('É verificar se existe algum problema na operação que seria melhor resolvido com uma ferramenta.',['Identificar o problema.','Registrar como é resolvido hoje.','Só depois avaliar se precisa de ferramenta.'],'Não queremos contratar ferramentas sem necessidade.',['Sempre comece pelo problema. Exemplo: “Estamos perdendo pedidos de suporte porque as mensagens estão espalhadas.”','Registre na tabela de necessidades.','Não indique marcas.'],'A empresa contrata ferramentas só quando resolvem problemas reais.'),
'tarefa:Levar as necessidades para decisão do responsável': T('É apresentar ao responsável os problemas registrados para ele decidir.',['Apresentar a tabela.','Marcar “Aguardando decisão”.'],'A decisão de contratar é da empresa.',['Revise a tabela com o responsável.','Marque cada necessidade como “Aguardando decisão”.'],'As decisões acontecem com base em fatos.',PERGUNTE),
'tarefa:Registrar as decisões tomadas': T('É anotar o que foi decidido para cada necessidade.',['Preencher o campo Decisão.'],'Evita rediscutir o mesmo assunto.',['Abra cada necessidade.','Escolha a decisão e escreva a observação.'],'Fica o histórico das decisões.'),
'tarefa:Listar as tarefas manuais repetitivas': T('É anotar tarefas que você faz à mão muitas vezes.',['Perceber repetições.','Registrar na tabela.'],'Mostra onde automatizar traz mais ganho.',['Durante a Operação diária, observe o que se repete.','Registre a tarefa, a frequência e o problema.'],'Cria a lista de candidatas à automação.'),
'tarefa:Priorizar as oportunidades com o responsável': T('É decidir com o responsável quais automações valem a pena.',['Apresentar a tabela.','Registrar a decisão.'],'Não se automatiza por automatizar.',['Revise com o responsável.','Marque Aprovada ou Descartada.'],'Foca o esforço no que traz mais retorno.',PERGUNTE),
'tarefa:Implantar as automações aprovadas': T('É colocar em funcionamento as automações que foram aprovadas.',['Implantar.','Testar.','Marcar como Implantada.'],'Reduz trabalho manual depois que o processo está organizado.',['Siga o que foi decidido pelo responsável.','Teste com casos reais.','Marque como Implantada.'],'O trabalho repetitivo diminui.','Não implante nada que não esteja aprovado.'),
'tarefa:Definir o destino definitivo de cada item': T('É decidir para onde vai cada coisa organizada aqui (rotinas, procedimentos, clientes, produtos…).',['Preencher o local definitivo de cada linha da tabela de Migração.'],'O painel não pode virar uma fonte paralela.',['Revise a tabela com o responsável.','Preencha o local definitivo de cada item.'],'Cada informação ganha um lugar oficial.',PERGUNTE),
'tarefa:Migrar as informações para os locais definitivos': T('É levar cada informação para o lugar definitivo escolhido.',['Migrar.','Marcar Migrado.','Pedir validação.'],'Enquanto a informação estiver aqui, o painel não pode ser encerrado.',['Leve o item para o local definitivo.','Marque “Migrado”.','Peça ao responsável para conferir e marque “Validado”.'],'Prepara o fim do painel.'),
'tarefa:Confirmar que o painel não é fonte paralela': T('É conferir que nenhuma informação existe só aqui.',['Revisar cada seção.'],'Garante que o painel pode ser desligado sem perda.',['Passe por cada seção.','Para cada informação, pergunte: “Isso já existe no local definitivo?”.','Anote o que faltar.'],'O painel pode ser encerrado com segurança.'),
'tarefa:Revisar a checklist de encerramento com o responsável': T('É passar pela checklist final item por item junto com o responsável.',['Marcar cada item que for verdade.'],'Encerrar com pendências traz a bagunça de volta.',['Agende um momento com o responsável.','Leiam cada item juntos.','Marquem só o que estiver realmente pronto.'],'Confirma que a organização está completa.'),
'tarefa:Operar uma semana sem consultar o painel': T('É trabalhar uma semana inteira usando apenas os locais definitivos, sem abrir este painel.',['Operar normalmente.','Anotar se precisou do painel.'],'É a prova de que a operação continua sem ele.',['Use só os locais definitivos.','Se precisar abrir o painel, anote o motivo nas observações.','Resolva o que faltou migrar.'],'Quando a semana passa sem o painel, a implantação terminou.'),
'bloco:funil-lista': A('Funis cadastrados','É a lista de todos os funis, com situação, alunos, data de criação, tempo no ar e quantidade de produtos.',['Clicar em “Ver funil” para abrir um funil.','Clicar em “+ Novo funil” para cadastrar outro.'],'Mostra de uma vez o que está rodando e o que está parado.',['Rodando: está vendendo agora.','Parado: pausado, pode voltar.','Encerrado (já rodou): não vende mais.','Em construção: ainda não foi ao ar.','“No ar há” é calculado a partir da data em “No ar desde”.'],'Dá uma visão rápida de toda a operação de vendas.'),
'bloco:funil-sobre': A('Sobre esse funil','É o texto com o contexto geral do funil, escrito pelo responsável.',['Ler este texto antes de atender alunos deste funil.'],'Explica a lógica do funil e o que é importante saber sobre ele.',['Leia o contexto.','Se algo não estiver claro, anote a dúvida e pergunte ao responsável.'],'Ajuda a entender o funil sem depender de explicação verbal.','Se o texto estiver vazio, peça ao responsável para preencher.'),
'bloco:funil-etapas': A('Etapas do funil','São os produtos oferecidos em sequência: front, upsells, downsells, order bumps ou assinatura.',['Adicionar uma etapa para cada produto do funil, na ordem em que aparecem.','Preencher os campos de cada etapa.'],'Cada etapa tem valor, links, entregáveis e recuperação próprios.',['Clique em “+ Adicionar etapa / produto”.','Escolha o tipo de etapa.','Preencha nome, valor e briefing da oferta.','Preencha links da página, checkout e VSL.','Preencha entregáveis, recuperação de PIX e boleto e grupo.','Use ↑ e ↓ para ajustar a ordem.'],'Mostra exatamente o que o aluno pode comprar e o que precisa receber em cada etapa.'),
'tarefa:Cadastrar todos os funis que estão rodando': T('É cadastrar no painel cada funil que está vendendo agora.',['Listar os funis rodando com o responsável.','Cadastrar cada um com todas as etapas.'],'É preciso saber exatamente o que está sendo vendido hoje.',['Vá em Funis e clique em “+ Novo funil”.','Preencha o nome e marque “Rodando”.','Preencha a data em “No ar desde”.','Adicione cada etapa do funil.'],'O suporte e a entrega passam a ter uma referência clara de cada funil ativo.'),
'tarefa:Cadastrar os funis que já rodaram': T('É cadastrar os funis antigos que ainda têm alunos ou histórico importante.',['Listar com o responsável.','Cadastrar com a situação “Encerrado (já rodou)”.'],'Alunos de funis antigos ainda podem precisar de suporte.',['Cadastre o funil.','Preencha o que souber.','Deixe o resto como A DEFINIR.'],'Nenhum aluno fica sem referência do que comprou.'),
'tarefa:Preencher as etapas de cada funil': T('É completar as informações de cada etapa dos funis cadastrados.',['Abrir cada funil.','Preencher todos os campos de cada etapa.'],'Sem essas informações, entrega e recuperação dependem de memória.',['Abra o funil.','Expanda a etapa.','Preencha oferta, links, entregáveis, recuperação e grupo.'],'Cada etapa fica pronta para ser atendida e entregue.'),
'tarefa:Registrar a recuperação de PIX e boleto por etapa': T('É anotar, em cada etapa, como a empresa recupera PIX e boleto não pagos.',['Preencher os campos de Recuperação de cada etapa.'],'Cada oferta pode ter uma abordagem diferente.',['Pergunte ao responsável como deve ser a recuperação de cada oferta.','Preencha PIX e Boleto na etapa.'],'A recuperação fica padronizada por oferta.','Não crie mensagens de recuperação sem aprovação do responsável.'),
'tarefa:Definir e-mail e WhatsApp de suporte de cada funil': T('É registrar qual e-mail e qual WhatsApp atendem os alunos de cada funil.',['Preencher o bloco Suporte desse funil.'],'O aluno precisa ser atendido pelo canal certo.',['Confirme com o responsável.','Preencha e-mail e WhatsApp no funil.'],'Cada funil tem canais de suporte claros.','Não invente e-mails ou números.'),
'tarefa:Atualizar os números de alunos de cada funil': T('É registrar quantos alunos há em cada funil e em cada etapa.',['Preencher os números do funil e das etapas.','Atualizar de tempos em tempos.'],'Mostra o tamanho de cada funil e quantos compraram o funil inteiro.',['Consulte o local onde as vendas aparecem.','Preencha alunos, quem comprou o funil inteiro, quem não comprou e quem está no grupo.','Preencha os números de cada etapa.'],'O responsável acompanha o funil com números reais.')
};
})();
